cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/product_inventory.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Products']);

// Category breakdown
const cats = {};
data.forEach(r => {
  const c = r.Category.toLowerCase();
  if (!cats[c]) cats[c] = { count: 0, totalPrice: 0, products: [] };
  cats[c].count++;
  cats[c].totalPrice += r.Price;
  cats[c].products.push(r.Name);
});

console.log('--- Category Breakdown ---');
Object.entries(cats).sort((a,b) => b[1].count - a[1].count).forEach(([cat, info]) => {
  console.log('  ' + cat + ': ' + info.count + ' products, avg price: \$' + (info.totalPrice / info.count).toFixed(2) + ', total value: \$' + info.totalPrice);
});

const prices = data.map(r => r.Price);
const totalValue = prices.reduce((a,b) => a+b, 0);
const avgPrice = totalValue / data.length;
const maxP = data.reduce((a,b) => a.Price > b.Price ? a : b);
const minP = data.filter(r => r.Price > 0).reduce((a,b) => a.Price < b.Price ? a : b);

console.log('\n--- Price Stats ---');
console.log('  Total inventory value: \$' + totalValue);
console.log('  Average price: \$' + avgPrice.toFixed(2));
console.log('  Most expensive: ' + maxP.Name + ' (\$' + maxP.Price + ')');
console.log('  Least expensive (excl. \$0): ' + minP.Name + ' (\$' + minP.Price + ')');

const inStock = data.filter(r => r['In Stock'] === 'Yes').length;
const outOfStock = data.length - inStock;
console.log('\n--- Stock Status ---');
console.log('  In stock: ' + inStock);
console.log('  Out of stock: ' + outOfStock);
"

cd /workspace && node -e "
const { Document, Packer, Paragraph, Table, TableRow, TableCell, TextRun, WidthType, AlignmentType, HeadingLevel, BorderStyle, ShadingType } = require('docx');
const XLSX = require('xlsx');
const fs = require('fs');

const wb = XLSX.readFile('testbed/data/product_inventory.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Products']);

// Compute stats
const cats = {};
data.forEach(r => {
  const c = r.Category.toLowerCase();
  if (!cats[c]) cats[c] = { count: 0, totalPrice: 0 };
  cats[c].count++;
  cats[c].totalPrice += r.Price;
});
const totalValue = data.reduce((s, r) => s + r.Price, 0);
const avgPrice = (totalValue / data.length).toFixed(2);
const maxP = data.reduce((a, b) => a.Price > b.Price ? a : b);
const minP = data.filter(r => r.Price > 0).reduce((a, b) => a.Price < b.Price ? a : b);
const inStock = data.filter(r => r['In Stock'] === 'Yes').length;

// Helper: bold + normal text in one paragraph
const mixedPara = (boldText, normalText, spacing) => new Paragraph({
  spacing: spacing || { after: 100 },
  children: [
    new TextRun({ text: boldText, bold: true, font: 'Calibri', size: 22 }),
    new TextRun({ text: normalText, font: 'Calibri', size: 22 }),
  ],
});

// Helper: create table header cell
const headerCell = (text) => new TableCell({
  shading: { type: ShadingType.SOLID, color: '2E74B5' },
  children: [new Paragraph({ children: [new TextRun({ text, bold: true, font: 'Calibri', size: 22, color: 'FFFFFF' })], alignment: AlignmentType.CENTER })],
});

// Helper: create table data cell
const dataCell = (text, align) => new TableCell({
  children: [new Paragraph({ children: [new TextRun({ text, font: 'Calibri', size: 22 })], alignment: align || AlignmentType.LEFT })],
});

// --- Build Category Table ---
const catSorted = Object.entries(cats).sort((a, b) => b[1].count - a[1].count);
const catHeaderRow = new TableRow({ children: ['Category', '# Products', 'Avg Price', 'Total Value'].map(h => headerCell(h)) });
const catDataRows = catSorted.map(([cat, info]) => new TableRow({
  children: [
    dataCell(cat.charAt(0).toUpperCase() + cat.slice(1)),
    dataCell(String(info.count), AlignmentType.CENTER),
    dataCell('\$' + (info.totalPrice / info.count).toFixed(2), AlignmentType.RIGHT),
    dataCell('\$' + info.totalPrice, AlignmentType.RIGHT),
  ],
}));
const catTable = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: [catHeaderRow, ...catDataRows],
});

// --- Build Product Table ---
const prodHeaderRow = new TableRow({ children: ['Product ID', 'Name', 'Category', 'Price', 'In Stock'].map(h => headerCell(h)) });
const prodDataRows = data.map(r => new TableRow({
  children: [
    dataCell(r['Product ID']),
    dataCell(r.Name),
    dataCell(r.Category),
    dataCell('\$' + r.Price, AlignmentType.RIGHT),
    dataCell(r['In Stock'], AlignmentType.CENTER),
  ],
}));
const prodTable = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: [prodHeaderRow, ...prodDataRows],
});

// --- Assemble Document ---
const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        heading: HeadingLevel.TITLE,
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
        children: [new TextRun({ text: 'Product Inventory Summary', bold: true, font: 'Calibri', size: 48, color: '2E74B5' })],
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 400 },
        children: [new TextRun({ text: 'Generated from data/product_inventory.xlsx', italics: true, font: 'Calibri', size: 22, color: '666666' })],
      }),

      // Overview Section
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 }, children: [new TextRun({ text: 'Overview', font: 'Calibri', color: '2E74B5' })] }),
      mixedPara('Total Products: ', String(data.length)),
      mixedPara('Total Inventory Value: ', '\$' + totalValue),
      mixedPara('Average Price: ', '\$' + avgPrice),

      // Stock status highlight
      new Paragraph({
        spacing: { before: 200, after: 200 },
        shading: { type: ShadingType.SOLID, color: 'E6F4EA' },
        children: [
          new TextRun({ text: '✔ Stock Status: ', bold: true, font: 'Calibri', size: 24, color: '1B7340' }),
          new TextRun({ text: 'All ' + inStock + ' out of ' + data.length + ' listed items are marked as In Stock = Yes. There are zero out-of-stock products in this inventory.', font: 'Calibri', size: 22, color: '1B7340' }),
        ],
      }),

      // Category Breakdown
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 }, children: [new TextRun({ text: 'Category Breakdown', font: 'Calibri', color: '2E74B5' })] }),
      new Paragraph({ spacing: { after: 150 }, children: [new TextRun({ text: 'The inventory spans ' + catSorted.length + ' categories. Electronics and Kitchen are the largest, each with 5 products.', font: 'Calibri', size: 22 })] }),
      catTable,

      // Price Highlights
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 }, children: [new TextRun({ text: 'Price Highlights', font: 'Calibri', color: '2E74B5' })] }),
      mixedPara('Most Expensive: ', maxP.Name + ' — \$' + maxP.Price),
      mixedPara('Least Expensive (excl. \$0): ', minP.Name + ' — \$' + minP.Price),
      mixedPara('Promotional Item: ', 'AUTUMN10 Cart Discount — \$0'),

      // Observations
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 }, children: [new TextRun({ text: 'Notable Observations', font: 'Calibri', color: '2E74B5' })] }),
      new Paragraph({ spacing: { after: 80 }, bullet: { level: 0 }, children: [new TextRun({ text: 'Electronics and Kitchen are the largest categories (5 products each), together accounting for ~58% of total inventory value.', font: 'Calibri', size: 22 })] }),
      new Paragraph({ spacing: { after: 80 }, bullet: { level: 0 }, children: [new TextRun({ text: 'All 20 products are confirmed In Stock (Yes) — no items are out of stock.', font: 'Calibri', size: 22 })] }),
      new Paragraph({ spacing: { after: 80 }, bullet: { level: 0 }, children: [new TextRun({ text: '\"Clothing\" and \"Apparel\" categories likely overlap and could be consolidated (4 items, \$234 total).', font: 'Calibri', size: 22 })] }),
      new Paragraph({ spacing: { after: 80 }, bullet: { level: 0 }, children: [new TextRun({ text: 'One promotional/discount entry (AUTUMN10 Cart Discount) is mixed in with physical products.', font: 'Calibri', size: 22 })] }),

      // Full Product Listing
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 }, children: [new TextRun({ text: 'Full Product Listing', font: 'Calibri', color: '2E74B5' })] }),
      new Paragraph({
        spacing: { after: 200 },
        children: [
          new TextRun({ text: 'Note: ', bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: 'Every product listed below has its \"In Stock\" status marked as \"Yes\".', font: 'Calibri', size: 22 }),
        ],
      }),
      prodTable,
    ],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('testbed/data/product_inventory_summary.docx', buf);
  console.log('Document saved successfully!');
  console.log('Size: ' + (buf.length / 1024).toFixed(1) + ' KB');
});
"
